"""Reports upstream protobuf source files added or removed between releases.

Chromium builds protobuf using hand-maintained GN lists in
//third_party/protobuf/proto_sources.gni and //third_party/protobuf/BUILD.gn
rather than upstream's Bazel or CMake build files. Upstream generates
src/file_lists.cmake from its Bazel rules (`@//pkg:gen_src_file_lists_cmake`),
listing every source and header file per library target.

Comparing upstream's src/file_lists.cmake directly against Chromium's GN files
produces mostly noise because Chromium intentionally omits large parts of
upstream (such as C#, Objective-C, Rust, PHP, and Ruby code generators).
Instead, this module diffs the old and new upstream src/file_lists.cmake files
and cross-checks that delta against Chromium's GN lists
(https://crbug.com/568001437):
  1. Added upstream files: files present in the new release's library lists
     that were absent in the old release's library lists and are not yet listed
     in Chromium's GN files, annotated with the number of sibling files in the
     same directory that Chromium already builds.
  2. Removed upstream files: files listed in Chromium's GN files that were
     removed from upstream's library lists or no longer exist on disk in the
     new upstream tree.
"""

from collections.abc import Sequence
import argparse
import dataclasses
import json
import os
import posixpath
import re
import subprocess
import sys

_PROTOBUF_DIRECTORY = os.path.dirname(os.path.abspath(__file__))

# Upstream CMake variable names in src/file_lists.cmake corresponding to the
# C++ runtime and protoc libraries that Chromium builds subsets of.
UPSTREAM_LIBRARY_LIST_NAMES = (
    'libprotobuf_lite_srcs',
    'libprotobuf_lite_hdrs',
    'libprotobuf_srcs',
    'libprotobuf_hdrs',
    'libprotoc_srcs',
    'libprotoc_hdrs',
    'libprotoc_public_srcs',
    'libprotoc_public_hdrs',
)

_CHROMIUM_GN_FILENAMES = (
    'proto_sources.gni',
    'BUILD.gn',
)

_TRACKED_SOURCE_DIRECTORY_PREFIXES = (
    'src/',
    'java/',
    'python/',
    'third_party/utf8_range/',
)

_TRACKED_SOURCE_EXTENSIONS = (
    '.c',
    '.cc',
    '.h',
    '.hpp',
    '.inc',
    '.java',
    '.py',
)

# Files under src/ and python/ generated by gen_extra_chromium_files.py during
# roll step 4. In a raw upstream archive (before step 4 runs), the Python
# outputs do not exist on disk yet, so they must not be flagged as removed.
_BOOTSTRAP_GENERATED_FILES = frozenset({
    'src/google/protobuf/descriptor.pb.h',
    'src/google/protobuf/descriptor.pb.cc',
    'src/google/protobuf/compiler/plugin.pb.h',
    'src/google/protobuf/compiler/plugin.pb.cc',
    'python/google/protobuf/descriptor_pb2.py',
    'python/google/protobuf/compiler/plugin_pb2.py',
    'python/google/protobuf/internal/python_edition_defaults.py',
})

_CMAKE_SET_BLOCK_PATTERN = re.compile(r'set\(([\w-]+)\n([^)]*)\)')
_CMAKE_SOURCE_PATH_PATTERN = re.compile(r'\$\{protobuf_SOURCE_DIR\}/(\S+)')
_GN_STRING_ASSIGNMENT_PATTERN = re.compile(
    r'^\s*(_[A-Za-z0-9_]*)\s*=\s*"([^"\n]*)"\s*$')

# Match string literals within a single line so a closing quote on one line can
# never pair with an opening quote on the next line.
_GN_SINGLE_LINE_STRING_PATTERN = re.compile(r'"([^"\n]*)"')


@dataclasses.dataclass(frozen=True)
class AddedUpstreamFile:
    """An upstream library file added in the new release and absent from GN.

    Attributes:
      path: POSIX path relative to //third_party/protobuf.
      upstream_lists: Tuple of UPSTREAM_LIBRARY_LIST_NAMES that include path.
      chromium_sibling_count: Number of files in the same directory that
        Chromium already lists in proto_sources.gni or BUILD.gn. A non-zero
        count strongly suggests Chromium builds this directory and needs path.
    """

    path: str
    upstream_lists: tuple[str, ...]
    chromium_sibling_count: int

    def ToDictionary(self) -> dict[str, object]:
        """Returns a JSON-serializable dictionary representation."""
        return {
            'path': self.path,
            'upstream_lists': list(self.upstream_lists),
            'chromium_sibling_count': self.chromium_sibling_count,
        }


@dataclasses.dataclass(frozen=True)
class FileListsDiff:
    """Unfollowed source-file additions and removals between two releases.

    Attributes:
      added_files: Upstream library files added in the new release that are not
        listed in Chromium's GN files, ordered by path.
      removed_files: Files listed in Chromium's GN files that were removed from
        upstream's library lists or no longer exist in the new upstream tree,
        ordered by path.
    """

    added_files: tuple[AddedUpstreamFile, ...]
    removed_files: tuple[str, ...]

    def HasUnfollowedChanges(self) -> bool:
        """Returns True if any added or removed files remain unfollowed."""
        return bool(self.added_files or self.removed_files)

    def ToDictionary(self) -> dict[str, object]:
        """Returns a JSON-serializable dictionary representation."""
        return {
            'added_files': [
                added_file.ToDictionary() for added_file in self.added_files
            ],
            'removed_files': list(self.removed_files),
        }


def ParseCmakeFileLists(cmake_text: str) -> dict[str, set[str]]:
    """Parses `set(<name> ...)` blocks from upstream's src/file_lists.cmake.

    Args:
      cmake_text: Full text content of a src/file_lists.cmake file.

    Returns:
      A dictionary mapping each CMake list name to the set of
      ${protobuf_SOURCE_DIR}-relative POSIX file paths in that list.
    """
    file_lists_by_name: dict[str, set[str]] = {}
    for block_match in _CMAKE_SET_BLOCK_PATTERN.finditer(cmake_text):
        list_name = block_match.group(1)
        list_body = block_match.group(2)
        relative_paths = _CMAKE_SOURCE_PATH_PATTERN.findall(list_body)
        file_lists_by_name.setdefault(list_name, set()).update(relative_paths)
    return file_lists_by_name


def _VariableNameLength(variable_entry: tuple[str, str]) -> int:
    """Returns the length of the GN variable name in a (name, value) pair."""
    return len(variable_entry[0])


def _ExpandGnVariables(raw_string: str, variables: dict[str, str]) -> str:
    """Expands `$var` and `${var}` placeholders using known GN variables."""
    expanded = raw_string
    # Replace longer variable names first so a shorter prefix variable (such as
    # `_cpp_dir`) cannot corrupt a longer variable (`_cpp_dir_internal`).
    for variable_name, variable_value in sorted(
            variables.items(), key=_VariableNameLength, reverse=True):
        expanded = expanded.replace(f'${{{variable_name}}}', variable_value)
        expanded = expanded.replace(f'${variable_name}', variable_value)
    return re.sub(r'/+', '/', expanded)


def _IsTrackedGnSourceFile(candidate_path: str) -> bool:
    """Returns True if candidate_path is a resolved protobuf source file."""
    if '$' in candidate_path or '{{' in candidate_path:
        return False
    has_tracked_prefix = candidate_path.startswith(
        _TRACKED_SOURCE_DIRECTORY_PREFIXES)
    has_tracked_extension = candidate_path.endswith(_TRACKED_SOURCE_EXTENSIONS)
    return has_tracked_prefix and has_tracked_extension


def ParseGnSourceFiles(gn_texts: Sequence[str]) -> set[str]:
    """Extracts protobuf source and header paths from GN file contents.

    Expands file-scoped path variables such as `_include_dir`, `_cpp_dir`,
    `_java_dir`, and `_python_dir` in declaration order before matching string
    literals on each line.

    Args:
      gn_texts: Sequence of text contents from proto_sources.gni and BUILD.gn,
        ordered so variable definitions precede their uses.

    Returns:
      A set of POSIX file paths relative to //third_party/protobuf.
    """
    variables: dict[str, str] = {}
    source_files: set[str] = set()

    for gn_text in gn_texts:
        for raw_line in gn_text.splitlines():
            line_without_comment = raw_line.split('#', 1)[0]
            assignment_match = _GN_STRING_ASSIGNMENT_PATTERN.match(
                line_without_comment)
            if assignment_match is not None:
                variable_name = assignment_match.group(1)
                expanded_value = _ExpandGnVariables(
                    assignment_match.group(2), variables)
                variables[variable_name] = expanded_value.rstrip('/')
                continue

            for literal in _GN_SINGLE_LINE_STRING_PATTERN.findall(
                    line_without_comment):
                expanded_literal = _ExpandGnVariables(literal, variables)
                if _IsTrackedGnSourceFile(expanded_literal):
                    source_files.add(expanded_literal)

    return source_files


def _ReadUtf8File(file_path: str) -> str:
    """Reads and returns the UTF-8 text contents of file_path."""
    with open(file_path, 'r', encoding='utf-8') as file_handle:
        return file_handle.read()


def ReadChromiumGnSourceFiles(protobuf_directory: str) -> set[str]:
    """Reads proto_sources.gni and BUILD.gn from protobuf_directory."""
    gn_texts = [
        _ReadUtf8File(os.path.join(protobuf_directory, filename))
        for filename in _CHROMIUM_GN_FILENAMES
    ]
    return ParseGnSourceFiles(gn_texts)


def _UnionTrackedUpstreamFiles(
        cmake_lists: dict[str, set[str]],
        list_names: Sequence[str]) -> set[str]:
    """Returns the union of all file paths in the specified CMake lists."""
    combined_files: set[str] = set()
    for list_name in list_names:
        combined_files.update(cmake_lists.get(list_name, set()))
    return combined_files


def _CountChromiumFilesByDirectory(
        chromium_gn_files: set[str]) -> dict[str, int]:
    """Counts how many files Chromium lists in each POSIX directory."""
    counts_by_directory: dict[str, int] = {}
    for relative_path in chromium_gn_files:
        directory = posixpath.dirname(relative_path)
        counts_by_directory[directory] = (
            counts_by_directory.get(directory, 0) + 1)
    return counts_by_directory


def _FindUnfollowedAddedFiles(
        old_upstream_files: set[str],
        new_upstream_files: set[str],
        new_cmake_lists: dict[str, set[str]],
        chromium_gn_files: set[str],
        list_names: Sequence[str],
) -> tuple[AddedUpstreamFile, ...]:
    """Builds AddedUpstreamFile entries for new upstream files absent in GN."""
    sibling_counts_by_directory = _CountChromiumFilesByDirectory(
        chromium_gn_files)
    unfollowed_added_paths = sorted(
        (new_upstream_files - old_upstream_files) - chromium_gn_files)

    added_files: list[AddedUpstreamFile] = []
    for relative_path in unfollowed_added_paths:
        containing_lists = tuple(
            list_name for list_name in list_names
            if relative_path in new_cmake_lists.get(list_name, set()))
        directory = posixpath.dirname(relative_path)
        sibling_count = sibling_counts_by_directory.get(directory, 0)
        added_files.append(
            AddedUpstreamFile(
                path=relative_path,
                upstream_lists=containing_lists,
                chromium_sibling_count=sibling_count,
            ))
    return tuple(added_files)


def _FindFilesMissingFromTree(
        chromium_gn_files: set[str],
        new_tree_directory: str | None) -> set[str]:
    """Returns non-bootstrap GN files absent from new_tree_directory."""
    if new_tree_directory is None:
        return set()

    missing_files: set[str] = set()
    for relative_path in chromium_gn_files:
        if relative_path in _BOOTSTRAP_GENERATED_FILES:
            continue
        full_path = os.path.join(new_tree_directory, *relative_path.split('/'))
        if not os.path.isfile(full_path):
            missing_files.add(relative_path)
    return missing_files


def ComputeFileListsDiff(
        old_cmake_text: str,
        new_cmake_text: str,
        chromium_gn_files: set[str],
        new_tree_directory: str | None = None,
        list_names: Sequence[str] = UPSTREAM_LIBRARY_LIST_NAMES,
) -> FileListsDiff:
    """Computes added and removed upstream files relative to Chromium GN lists.

    Args:
      old_cmake_text: Contents of the previous release's src/file_lists.cmake.
      new_cmake_text: Contents of the new release's src/file_lists.cmake.
      chromium_gn_files: Set of relative paths currently listed in Chromium's
        proto_sources.gni and BUILD.gn.
      new_tree_directory: Optional path to the new upstream tree on disk. When
        provided, any file in chromium_gn_files (excluding bootstrap-generated
        files) that does not exist under new_tree_directory is also reported in
        removed_files.
      list_names: Upstream CMake variable names to inspect.

    Returns:
      A FileListsDiff containing unfollowed added_files and removed_files.
    """
    old_cmake_lists = ParseCmakeFileLists(old_cmake_text)
    new_cmake_lists = ParseCmakeFileLists(new_cmake_text)

    old_upstream_files = _UnionTrackedUpstreamFiles(old_cmake_lists, list_names)
    new_upstream_files = _UnionTrackedUpstreamFiles(new_cmake_lists, list_names)

    added_files = _FindUnfollowedAddedFiles(
        old_upstream_files=old_upstream_files,
        new_upstream_files=new_upstream_files,
        new_cmake_lists=new_cmake_lists,
        chromium_gn_files=chromium_gn_files,
        list_names=list_names,
    )

    removed_from_cmake = (
        (old_upstream_files - new_upstream_files) & chromium_gn_files)
    missing_from_new_tree = _FindFilesMissingFromTree(
        chromium_gn_files, new_tree_directory)
    removed_files = tuple(sorted(removed_from_cmake | missing_from_new_tree))

    return FileListsDiff(
        added_files=added_files,
        removed_files=removed_files,
    )


def FormatFileListsDiffReport(diff: FileListsDiff) -> str:
    """Formats a human-readable summary of added and removed upstream files."""
    if not diff.HasUnfollowedChanges():
        return (
            'No unfollowed upstream file additions or removals between '
            'src/file_lists.cmake and Chromium GN lists.')

    lines: list[str] = []
    if diff.added_files:
        lines.append(
            f'Upstream files added in src/file_lists.cmake and not listed in '
            f'proto_sources.gni / BUILD.gn ({len(diff.added_files)}):')
        for added_file in diff.added_files:
            lists_summary = ', '.join(added_file.upstream_lists)
            lines.append(
                f'  + {added_file.path} '
                f'[{lists_summary}] '
                f'(siblings in Chromium GN: '
                f'{added_file.chromium_sibling_count})')

    if diff.removed_files:
        if lines:
            lines.append('')
        lines.append(
            f'Files listed in proto_sources.gni / BUILD.gn that were removed '
            f'upstream ({len(diff.removed_files)}):')
        for removed_path in diff.removed_files:
            lines.append(f'  - {removed_path}')

    return '\n'.join(lines)


def _ReadGitFileAtRevision(
        protobuf_directory: str,
        git_revision: str,
        relative_path: str) -> str:
    """Reads a file relative to protobuf_directory from git at git_revision."""
    return subprocess.check_output(
        ['git', '-C', protobuf_directory, 'show',
         f'{git_revision}:./{relative_path}'],
        text=True,
    )


def _ReadOldCmakeFileLists(
        arguments: argparse.Namespace,
        protobuf_directory: str) -> str:
    """Reads the baseline src/file_lists.cmake from disk or git revision."""
    if arguments.old_cmake_path:
        return _ReadUtf8File(arguments.old_cmake_path)
    return _ReadGitFileAtRevision(
        protobuf_directory, arguments.old_revision, 'src/file_lists.cmake')


def _ReadNewCmakeFileLists(
        arguments: argparse.Namespace,
        new_tree_directory: str) -> str:
    """Reads the target release's src/file_lists.cmake from disk."""
    new_cmake_path = (
        arguments.new_cmake_path if arguments.new_cmake_path else os.path.join(
            new_tree_directory, 'src', 'file_lists.cmake'))
    return _ReadUtf8File(new_cmake_path)


def _ParseCommandLineArguments(
        command_line_arguments: Sequence[str] | None) -> argparse.Namespace:
    """Parses command-line options for standalone execution."""
    parser = argparse.ArgumentParser(
        description=(
            'Diffs old and new upstream src/file_lists.cmake against '
            'Chromium proto_sources.gni and BUILD.gn.'))
    parser.add_argument(
        '--protobuf-dir',
        default=_PROTOBUF_DIRECTORY,
        dest='protobuf_directory',
        help='Path to //third_party/protobuf (default: script directory).')
    parser.add_argument(
        '--old-cmake',
        dest='old_cmake_path',
        help=(
            'Path to the old upstream src/file_lists.cmake. If omitted, '
            'reads <old-rev>:./src/file_lists.cmake via git show.'))
    parser.add_argument(
        '--old-rev',
        default='HEAD',
        dest='old_revision',
        help=(
            'Git revision used to read the old src/file_lists.cmake when '
            '--old-cmake is not set (default: HEAD).'))
    parser.add_argument(
        '--new-tree',
        dest='new_tree_directory',
        help=(
            'Path to the new upstream protobuf root directory '
            '(default: --protobuf-dir).'))
    parser.add_argument(
        '--new-cmake',
        dest='new_cmake_path',
        help=(
            'Path to the new upstream src/file_lists.cmake '
            '(default: <new-tree>/src/file_lists.cmake).'))
    parser.add_argument(
        '--json',
        action='store_true',
        dest='should_output_json',
        help='Print the diff as machine-readable JSON.')
    return parser.parse_args(command_line_arguments)


def main(command_line_arguments: Sequence[str] | None = None) -> int:
    """Runs the file-list diff CLI and prints the report."""
    arguments = _ParseCommandLineArguments(command_line_arguments)
    protobuf_directory = os.path.abspath(arguments.protobuf_directory)
    new_tree_directory = os.path.abspath(
        arguments.new_tree_directory
        if arguments.new_tree_directory else protobuf_directory)

    diff = ComputeFileListsDiff(
        old_cmake_text=_ReadOldCmakeFileLists(arguments, protobuf_directory),
        new_cmake_text=_ReadNewCmakeFileLists(arguments, new_tree_directory),
        chromium_gn_files=ReadChromiumGnSourceFiles(protobuf_directory),
        new_tree_directory=new_tree_directory,
    )

    if arguments.should_output_json:
        print(json.dumps(diff.ToDictionary(), indent=2))
    else:
        print(FormatFileListsDiffReport(diff))
    return 0


if __name__ == '__main__':
    sys.exit(main())
